// Decides whether one outbound WhatsApp message may be sent through the
// WhatsApp Business Platform (Cloud API). Pure function: no I/O, no storage.
//
// Rules, checked in this order:
//   1. The patient must have opted in to WhatsApp messages from us.
//   2. The message type must be "text" (free-form) or "template" (pre-approved).
//   3. Free-form text needs an open customer service window: the patient must
//      have sent us a message less than 24 hours ago.
//      Templates skip this rule.

const WINDOW_MS = 24 * 60 * 60 * 1000;

// Meta sends webhook `timestamp` as Unix time in seconds, as a string.
// Allow a few minutes of clock skew between Meta and our server; anything
// further ahead is treated as malformed (for example, milliseconds).
const MAX_FUTURE_SKEW_MS = 5 * 60 * 1000;

export function decideWhatsApp(message, now) {
  const { type, contact } = message;

  if (contact?.optedIn !== true) {
    return { allowed: false, reason: "not_opted_in" };
  }

  if (type === "template") {
    return { allowed: true, reason: null };
  }

  if (type !== "text") {
    return { allowed: false, reason: "unknown_message_type" };
  }

  const last = contact.lastInboundTimestamp;

  // Never written to us: no window has ever opened.
  if (last === null || last === undefined) {
    return { allowed: false, reason: "outside_service_window" };
  }

  if (typeof last !== "string" || !/^\d+$/.test(last)) {
    return { allowed: false, reason: "invalid_inbound_timestamp" };
  }

  const inboundMs = Number(last) * 1000;
  const nowMs = now.getTime();

  if (!Number.isFinite(inboundMs) || inboundMs > nowMs + MAX_FUTURE_SKEW_MS) {
    return { allowed: false, reason: "invalid_inbound_timestamp" };
  }

  // Strictly less than 24 hours: the window is closed at exactly 24 hours.
  if (nowMs - inboundMs < WINDOW_MS) {
    return { allowed: true, reason: null };
  }

  return { allowed: false, reason: "outside_service_window" };
}

input.command:
node --input-type=module -e '
import { decideWhatsApp as d } from "./bot.mjs";
const now = new Date("2026-01-03T00:00:00Z"); // 1767398400
const T = (s) => String(Math.floor(s / 1000));
const base = (ts, optedIn = true) => ({ optedIn, lastInboundTimestamp: ts });
const cases = [
  ["text in window", { type: "text", contact: base(T(now - 3600e3)) }, { allowed: true, reason: null }],
  ["text exactly 24h", { type: "text", contact: base(T(now - 86400e3)) }, { allowed: false, reason: "outside_service_window" }],
  ["text 24h-1s", { type: "text", contact: base(T(now - 86400e3 + 1000)) }, { allowed: true, reason: null }],
  ["text expired", { type: "text", contact: base(T(now - 3 * 86400e3)) }, { allowed: false, reason: "outside_service_window" }],
  ["text never inbound", { type: "text", contact: base(null) }, { allowed: false, reason: "outside_service_window" }],
  ["text small clock skew future", { type: "text", contact: base(T(now + 30e3)) }, { allowed: true, reason: null }],
  ["text ms timestamp", { type: "text", contact: base(String(now.getTime() - 3600e3)) }, { allowed: false, reason: "invalid_inbound_timestamp" }],
  ["text numeric (not string)", { type: "text", contact: base(Math.floor(now / 1000) - 60) }, { allowed: false, reason: "invalid_inbound_timestamp" }],
  ["template never inbound", { type: "template", contact: base(null) }, { allowed: true, reason: null }],
  ["template expired", { type: "template", contact: base(T(now - 9 * 86400e3)) }, { allowed: true, reason: null }],
  ["not opted in text", { type: "text", contact: base(T(now - 60e3), false) }, { allowed: false, reason: "not_opted_in" }],
  ["not opted in template", { type: "template", contact: base(null, false) }, { allowed: false, reason: "not_opted_in" }],
  ["unknown type", { type: "image", contact: base(T(now - 60e3)) }, { allowed: false, reason: "unknown_message_type" }],
];
let fail = 0;
for (const [name, m, want] of cases) {
  const got = d(m, now);
  const ok = JSON.stringify(got) === JSON.stringify(want);
  if (!ok) fail++;
  console.log(ok ? "PASS" : "FAIL", name, JSON.stringify(got));
}
console.log(fail ? `${fail} FAILED` : "all passed");
'

